INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_arogga', '{"sections":[{"id":"services","title":{"en":"Ordering & healthcare services","bn":"অর্ডার ও স্বাস্থ্যসেবা"},"body":{"en":"Arogga combines medicine and healthcare-product ordering with home sample collection for lab tests and online doctor consultations. Customers can search by medicine name or upload a prescription. The consultation page offers general-doctor consultations; specialist appointment booking is marked as coming soon.","bn":"Arogga-তে ওষুধ ও স্বাস্থ্যপণ্য অর্ডারের পাশাপাশি বাসা থেকে পরীক্ষার নমুনা সংগ্রহ এবং অনলাইনে ডাক্তারের পরামর্শ নেওয়ার সেবা আছে। ওষুধের নাম দিয়ে খোঁজা বা প্রেসক্রিপশনের ছবি আপলোড করা যায়। সাধারণ ডাক্তারের সঙ্গে কথা বলার সুযোগ থাকলেও বিশেষজ্ঞের অ্যাপয়েন্টমেন্ট নেওয়ার সুবিধাটি এখনো চালুর অপেক্ষায় বলে লেখা আছে।"},"sources":[{"title":"Ordering & healthcare services","url":"https://www.arogga.com/","publishedOn":null,"checkedAt":"2026-09-21"},{"title":"Doctor consultation availability","url":"https://www.arogga.com/online-doctor-consultation","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":null,"phone":"09610016778","address":{"en":"D/15-1, Road 36, Block D, Section 10, Mirpur, Dhaka 1216.","bn":"ডি/১৫-১, রোড ৩৬, ব্লক ডি, সেকশন ১০, মিরপুর, ঢাকা ১২১৬।"},"sources":[{"title":"Official contact information","url":"https://www.arogga.com/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
