INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_bkash', '{"sections":[{"id":"services","title":{"en":"Consumer & business services","bn":"ব্যক্তিগত লেনদেন ও ব্যবসার সেবা"},"body":{"en":"bKash supports person-to-person transfers, merchant payments, mobile recharge, bill payment and cash withdrawal. Its business offering has separate routes for online sellers, merchants, educational institutions and corporate customers, including digital payroll. Savings, loans and insurance appear as additional service categories; product eligibility and terms should be checked separately.","bn":"টাকা পাঠানো, দোকানে পেমেন্ট, মোবাইল রিচার্জ, বিল দেওয়া ও ক্যাশ আউট করা যায় bKash দিয়ে। অনলাইন বিক্রেতা, মার্চেন্ট, শিক্ষাপ্রতিষ্ঠান ও করপোরেট গ্রাহকদের জন্য আলাদা সেবাও আছে, যেমন ডিজিটাল বেতন দেওয়া। সঞ্চয়, ঋণ ও বিমার সুবিধা নিতে কারা পারবেন এবং কী শর্ত আছে, তা সংশ্লিষ্ট প্রোডাক্টের পেজে দেখে নিতে হয়।"},"sources":[{"title":"Consumer & business services","url":"https://www.bkash.com/en","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":null,"phone":"16247","address":null,"sources":[{"title":"Official contact information","url":"https://www.bkash.com/en/customer-service/contact-us","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
