INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_shikho', '{"sections":[{"id":"services","title":{"en":"Academic learning & exam preparation","bn":"পড়াশোনা ও পরীক্ষার প্রস্তুতি"},"body":{"en":"Shikho combines live and recorded classes with animated lessons, class notes, practice and live multiple-choice tests, and report cards. Its academic and admission-preparation programmes serve school and college learners.","bn":"স্কুল-কলেজের পড়া ও ভর্তি পরীক্ষার প্রস্তুতিতে Shikho-তে লাইভ ও রেকর্ডেড ক্লাস করা যায়। সঙ্গে আছে অ্যানিমেটেড পাঠ, ক্লাস নোট, অনুশীলনী ও লাইভ বহুনির্বাচনী পরীক্ষা এবং রিপোর্ট কার্ড।"},"sources":[{"title":"Academic learning & exam preparation","url":"https://shikho.com/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":"team@shikho.com","phone":"16780","address":{"en":"Rangs Paramount, Level 11, Block K, Plot 11, Road 17, Dhaka 1213.","bn":"র‍্যাংগস প্যারামাউন্ট, লেভেল ১১, ব্লক কে, প্লট ১১, রোড ১৭, ঢাকা ১২১৩।"},"sources":[{"title":"Official contact information","url":"https://shikho.com/en/about-us","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
