INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_reverse-resources', '{"sections":[{"id":"services","title":{"en":"Textile waste data & traceability","bn":"টেক্সটাইল বর্জ্যের তথ্য ও গতিপথ"},"body":{"en":"Reverse Resources connects fashion brands, textile manufacturers, waste handlers and recyclers. Its platform records waste flows and material composition so participants can identify recycling feedstock and follow it through the supply chain. Manufacturers get waste records and reporting tools; brands can view material-flow reports across participating suppliers.","bn":"কাপড়ের বর্জ্য কোথা থেকে এল, কী উপাদান আছে আর রিসাইক্লারের কাছে কীভাবে পৌঁছাল, সেই তথ্য রাখা যায় Reverse Resources-এ। ফ্যাশন ব্র্যান্ড, কারখানা, বর্জ্য সংগ্রহকারী ও রিসাইক্লাররা এতে যুক্ত হন। কারখানার জন্য বর্জ্যের হিসাব ও রিপোর্টের টুল আছে, আর ব্র্যান্ডগুলো সংশ্লিষ্ট সরবরাহকারীদের উপকরণ চলাচলের রিপোর্ট দেখতে পারে।"},"sources":[{"title":"Textile waste data & traceability","url":"https://www.reverseresources.net/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":"info@reverseresources.net","phone":null,"address":{"en":"Telliskivi 60A, ON-building, fourth floor, Tallinn, Estonia.","bn":"তেল্লিসকিভি ৬০এ, ওএন বিল্ডিং, চতুর্থ তলা, তাল্লিন, এস্তোনিয়া।"},"sources":[{"title":"Official contact information","url":"https://www.reverseresources.net/contact","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
