INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_agricore', '{"sections":[{"id":"services","title":{"en":"Farm records & asset verification","bn":"খামারের হিসাব ও সম্পদ যাচাই"},"body":{"en":"The InsureCow website describes livestock registration, health and vaccination records, milk-production and feed logs, breeding records and farm income/expense reports. Its enterprise offering includes animal identification, muzzle-pattern recognition and integrations with institutional systems. The website still uses InsureCow branding; this profile retains the existing AgriCore identity and historical name.","bn":"গরু নিবন্ধন, স্বাস্থ্য ও টিকার রেকর্ড, দুধ উৎপাদন, খাবার, প্রজনন এবং খামারের আয়-ব্যয়ের হিসাব রাখার সুবিধা InsureCow-এর সাইটে দেওয়া আছে। বড় প্রতিষ্ঠানের জন্য প্রাণী শনাক্ত করা, নাকের ছাপ মিলিয়ে দেখা ও অন্য সফটওয়্যারের সঙ্গে যুক্ত করার সেবাও বর্ণনা করা হয়েছে। সাইটে এখনো InsureCow নামই আছে। এখানে আগের AgriCore পরিচয় ও পুরোনো নাম দুটোই রাখা হয়েছে।"},"sources":[{"title":"Farm records & asset verification","url":"https://insurecow.com/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":"info@insurecow.com","phone":"+8801999467873","address":{"en":"Bangladesh: House 117, Road 5, Block B, Niketon, Dhaka. Singapore: 192 Waterloo Street, #05-03 Skyline, Singapore 187966.","bn":"বাংলাদেশ: বাড়ি ১১৭, রোড ৫, ব্লক বি, নিকেতন, ঢাকা। সিঙ্গাপুর: ১৯২ ওয়াটারলু স্ট্রিট, #০৫-০৩ স্কাইলাইন, সিঙ্গাপুর ১৮৭৯৬৬।"},"sources":[{"title":"Official contact information","url":"https://insurecow.com/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
