INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_agroshift', '{"sections":[{"id":"services","title":{"en":"Sourcing, distribution & trade","bn":"পণ্য সংগ্রহ, বিতরণ ও বাণিজ্য"},"body":{"en":"Agroshift aggregates demand for essential goods around workplaces such as factories and through resellers. It also supplies raw materials to food processors, supports contract manufacturing and private-label products, and coordinates cross-border trade and logistics for commodities such as pulses, wheat, rice and edible oil.","bn":"কারখানার মতো কর্মস্থল ও রিসেলারদের মাধ্যমে নিত্যপণ্যের চাহিদা একত্র করে Agroshift। খাদ্য প্রক্রিয়াজাতকারী প্রতিষ্ঠানে কাঁচামাল সরবরাহ, চুক্তিতে পণ্য তৈরি ও নিজস্ব ব্র্যান্ডে পণ্য বাজারে আনার কাজেও সহায়তা করে। ডাল, গম, চাল ও ভোজ্যতেলের আন্তর্জাতিক বাণিজ্য এবং পণ্য পরিবহনের ব্যবস্থাও তাদের কাজের অংশ।"},"sources":[{"title":"Sourcing, distribution & trade","url":"https://www.agroshift.com/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":"hello@agroshift.com","phone":null,"address":{"en":"Bangladesh: House 76/A, Road 11, Dhaka 1213. Global HQ: 101 Thompson Road, 12-01 United Square, Singapore 307591.","bn":"বাংলাদেশ: বাড়ি ৭৬/এ, রোড ১১, ঢাকা ১২১৩। প্রধান কার্যালয়: ১০১ থম্পসন রোড, ১২-০১ ইউনাইটেড স্কয়ার, সিঙ্গাপুর ৩০৭৫৯১।"},"sources":[{"title":"Official contact information","url":"https://www.agroshift.com/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
