INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_airwork', '{"sections":[{"id":"services","title":{"en":"Hiring software & managed recruitment","bn":"নিয়োগের সফটওয়্যার ও টিমের সহায়তা"},"body":{"en":"Airwork offers two hiring routes. Teams can use its software to post jobs, add screening questions and assessments, rank applicants and schedule interviews. Alternatively, its managed service handles sourcing and screening for full-time hires, contract staff or project teams, leaving the client to conduct final interviews. AI interviews and CRM are labeled coming soon.","bn":"Airwork-এ নিজে নিয়োগপ্রক্রিয়া চালানো বা তাদের টিমের সহায়তা নেওয়া যায়। সফটওয়্যার দিয়ে চাকরির বিজ্ঞপ্তি, প্রাথমিক প্রশ্ন ও দক্ষতার পরীক্ষা দেওয়া, আবেদনকারীদের বাছাই এবং ইন্টারভিউয়ের সময় ঠিক করা যায়। সেবাটি টিমকে দিলে তারা পূর্ণকালীন, চুক্তিভিত্তিক বা প্রজেক্টের জন্য লোক খুঁজে বাছাই করে দেয়। চূড়ান্ত ইন্টারভিউ নেয় নিয়োগদাতা। AI ইন্টারভিউ ও CRM এখনো চালুর অপেক্ষায় বলে চিহ্নিত।"},"sources":[{"title":"Hiring software & managed recruitment","url":"https://airwork.ai/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":null,"phone":null,"address":null,"sources":[{"title":"Official contact information","url":"https://airwork.ai/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
