INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_amarlab', '{"sections":[{"id":"services","title":{"en":"Home and workplace diagnostics","bn":"বাসা ও কর্মস্থল থেকে পরীক্ষা"},"body":{"en":"AmarLab lets customers choose a partner laboratory and book diagnostic tests for sample collection at home or work. Its technicians collect and transport samples, and the partner laboratory performs the tests. Reports are then delivered to the customer. Orders can be placed through the website, Messenger or telephone, with collection arrangements confirmed by the team.","bn":"বাসা বা কর্মস্থল থেকে নমুনা দিয়ে পরীক্ষা করাতে AmarLab-এ পছন্দের পার্টনার ল্যাব বেছে নেওয়া যায়। তাদের টেকনিশিয়ান নমুনা সংগ্রহ করে ল্যাবে পৌঁছে দেন। পরীক্ষা করে পার্টনার ল্যাব, এরপর রিপোর্ট গ্রাহকের কাছে আসে। ওয়েবসাইট, মেসেঞ্জার বা ফোনে অর্ডার দিলে নমুনা নেওয়ার সময় ও ব্যবস্থা টিমের সঙ্গে ঠিক করে নেওয়া যায়।"},"sources":[{"title":"Home and workplace diagnostics","url":"https://amarlab.com/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":"info@amarlab.com","phone":"09643445566","address":{"en":"Grameen Telecom Bhaban, Level 9, 53/1 Box Nagar, Mirpur, Dhaka 1216.","bn":"গ্রামীণ টেলিকম ভবন, লেভেল ৯, ৫৩/১ বক্স নগর, মিরপুর, ঢাকা ১২১৬।"},"sources":[{"title":"AmarLab - packages and contact","url":"https://amarlab.com/packages","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
