INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_appscode', '{"sections":[{"id":"services","title":{"en":"Database operations & cloud services","bn":"ডেটাবেস চালানো ও ক্লাউড সেবা"},"body":{"en":"AppsCode builds tools for technical teams operating Kubernetes infrastructure. KubeDB handles database provisioning and routine operations, KubeStash provides backup and recovery, and KubeVault manages secrets through HashiCorp Vault. Alongside these products, AppsCode offers managed cloud and database services, platform engineering, application modernization and reliability support.","bn":"Kubernetes-এ সফটওয়্যার চালানো টেকনিক্যাল টিমের জন্য AppsCode টুল তৈরি করে। KubeDB দিয়ে ডেটাবেস তৈরি ও নিয়মিত কাজ সামলানো, KubeStash দিয়ে ব্যাকআপ রাখা ও ফিরিয়ে আনা এবং KubeVault দিয়ে গোপন তথ্য ব্যবস্থাপনা করা যায়। প্রোডাক্টের পাশাপাশি ক্লাউড ও ডেটাবেস চালানো, পুরোনো অ্যাপ আধুনিক করা এবং নির্ভরযোগ্যভাবে সিস্টেম চালু রাখার সেবাও দেয়।"},"sources":[{"title":"Database operations & cloud services","url":"https://appscode.com/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":null,"phone":"+16502418486","address":null,"sources":[{"title":"Official contact information","url":"https://appscode.com/about/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
