INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_aunkur', '{"sections":[{"id":"services","title":{"en":"Farm data tools","bn":"খামারের তথ্য সংগ্রহের টুল"},"body":{"en":"Aunkur’s official site presents the iPAGE farm-data business: ALBATROSS is a portable solar-powered weather station, AUNKUR is an IoT-enabled rapid soil-testing device, and AUNKUR POS is a smartphone access point for agricultural service providers. Its intended users include farmers, input retailers, extension workers, banks and insurers seeking farm-specific information.","bn":"iPAGE-এর কৃষিতথ্যের ব্যবসা ও প্রোডাক্টগুলো Aunkur-এর সাইটে বর্ণনা করা আছে। ALBATROSS সৌরবিদ্যুতে চলে এমন বহনযোগ্য আবহাওয়া স্টেশন, AUNKUR মাটির দ্রুত পরীক্ষা করার সংযুক্ত যন্ত্র। আর AUNKUR POS দিয়ে স্মার্টফোনে কৃষিসেবার তথ্য পাওয়া যায়। কৃষক ছাড়াও উপকরণ বিক্রেতা, মাঠকর্মী, ব্যাংক ও বিমা প্রতিষ্ঠান এই তথ্য কাজে লাগাতে পারে।"},"sources":[{"title":"Farm data tools","url":"https://www.aunkur.ai/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":null,"phone":null,"address":null,"sources":[{"title":"Official contact information","url":"https://www.aunkur.ai/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
