INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_barikoi', '{"sections":[{"id":"services","title":{"en":"Maps, address search & routing","bn":"মানচিত্র, ঠিকানা খোঁজা ও রুট"},"body":{"en":"Barikoi supplies base maps, address search and geocoding, navigation and routing, and mobile SDKs. Businesses can use these components for parcel delivery, pickup locations, field-service routing and address checks. The website describes a focus on emerging markets; available coverage and a particular address should be tested before integration.","bn":"Barikoi-এর মানচিত্র, ঠিকানা খোঁজা, ঠিকানা থেকে অবস্থান বের করা ও রুটের টুল অ্যাপে যুক্ত করা যায়। পার্সেল পৌঁছানো, যাত্রী তোলার জায়গা ঠিক করা, মাঠকর্মীদের পথ সাজানো এবং ঠিকানা যাচাইয়ের কাজে এগুলো ব্যবহার করা যায়। সেবা নেওয়ার আগে প্রয়োজনের এলাকা ও কয়েকটি বাস্তব ঠিকানা দিয়ে ফল মিলিয়ে নেওয়া ভালো।"},"sources":[{"title":"Maps, address search & routing","url":"https://barikoi.com/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":null,"phone":null,"address":null,"sources":[{"title":"Official contact information","url":"https://barikoi.com/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
INSERT INTO identity_events (id, organization_id, action, actor, created_at, detail_json) VALUES ('catalogue-profile-barikoi', 'org_barikoi', 'review', 'editorial:company-profile-catalogue', '2026-09-21', '{"scope":"Bilingual products, services and evidenced contact details. Existing editorial research dates preserved."}');
INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_bimafy', '{"sections":[{"id":"services","title":{"en":"Policy comparison & claims support","bn":"পলিসি তুলনা ও দাবির সহায়তা"},"body":{"en":"Bimafy offers health, travel, accident, life and vehicle insurance options, alongside employee group, marine and fire insurance for businesses. Customers can compare coverage and manage policies through its app, submit claims and follow claim updates. The underlying insurer and the specific policy terms determine coverage; the marketplace listing does not replace those terms.","bn":"স্বাস্থ্য, ভ্রমণ, দুর্ঘটনা, জীবন ও গাড়ির বিমা বেছে নেওয়ার সুযোগ আছে Bimafy-তে। ব্যবসার জন্য কর্মীদের গ্রুপ বিমা, নৌপণ্য ও অগ্নিবিমাও আছে। অ্যাপে পলিসি দেখা, দাবি জমা দেওয়া এবং দাবির অগ্রগতি অনুসরণ করা যায়। কোন ক্ষতি কভার হবে, তা নির্ভর করে বিমা কোম্পানি ও নির্দিষ্ট পলিসির শর্তের ওপর।"},"sources":[{"title":"Policy comparison & claims support","url":"https://bimafy.com/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":null,"phone":"+8809606991991","address":null,"sources":[{"title":"Official contact information","url":"https://bimafy.com/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
