INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_bongo', '{"sections":[{"id":"services","title":{"en":"Entertainment distribution & content work","bn":"বিনোদন বিতরণ ও কনটেন্টের কাজ"},"body":{"en":"Bongo’s business portal describes distribution of Bangla films, dramas, television shows and music through its streaming service, mobile app and syndicated channels. It also works on original content and invites creators to discuss publishing their work. Business and content enquiries have a dedicated contact route.","bn":"Bongo-এর স্ট্রিমিং সেবা, অ্যাপ ও অন্য চ্যানেলের মাধ্যমে বাংলা সিনেমা, নাটক, টিভি অনুষ্ঠান ও গান দর্শকের কাছে পৌঁছায়। নিজস্ব কনটেন্ট তৈরির কাজও করে তারা। কোনো নির্মাতা নিজের কাজ প্রকাশ করতে চাইলে ব্যবসায়িক যোগাযোগের ঠিকানায় আলোচনা করতে পারেন।"},"sources":[{"title":"Entertainment distribution & content work","url":"https://business.bongobd.com/about-us/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":"business@bongobd.com","phone":"+8809613827262","address":{"en":"House 20, Road 2/B, Block J, Baridhara, Dhaka 1212.","bn":"বাড়ি ২০, রোড ২/বি, ব্লক জে, বারিধারা, ঢাকা ১২১২।"},"sources":[{"title":"Official contact information","url":"https://business.bongobd.com/contact-us-03/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
