INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_cassetex', '{"sections":[{"id":"services","title":{"en":"Battery swapping as a service","bn":"ব্যাটারি বদলে নেওয়ার সেবা"},"body":{"en":"Cassetex describes a battery-service network for electric three-wheelers, two-wheelers and agricultural equipment. An operator checks charge status, finds a swapping point, returns the used battery and collects a charged one. The company combines swapping operations with solar charging and energy-demand management; network coverage needs checking for a particular route.","bn":"বৈদ্যুতিক তিন চাকার যান, দুই চাকার যান ও কৃষিযন্ত্রের জন্য ব্যাটারির সেবা দেয় Cassetex। চালক চার্জের অবস্থা দেখে নিকটবর্তী স্টেশনে গিয়ে ব্যবহৃত ব্যাটারি জমা দেন, তারপর চার্জ করা ব্যাটারি নিয়ে চলতে পারেন। এই ব্যবস্থার সঙ্গে সৌরবিদ্যুতে চার্জ দেওয়া ও বিদ্যুতের চাহিদা সামলানোর কাজও আছে। নিজের রুটে স্টেশন আছে কি না, আগে দেখে নিতে হবে।"},"sources":[{"title":"Battery swapping as a service","url":"https://www.cassetex.com/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":"team@cassetex.com","phone":"+8801324414400","address":{"en":"Dhaka, Bangladesh.","bn":"ঢাকা, বাংলাদেশ।"},"sources":[{"title":"Official contact information","url":"https://www.cassetex.com/contact/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
INSERT INTO identity_events (id, organization_id, action, actor, created_at, detail_json) VALUES ('catalogue-profile-cassetex', 'org_cassetex', 'review', 'editorial:company-profile-catalogue', '2026-09-21', '{"scope":"Bilingual products, services and evidenced contact details. Existing editorial research dates preserved."}');
INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_chamak', '{"sections":[{"id":"services","title":{"en":"Trade-linked working capital","bn":"বেচাকেনার সঙ্গে যুক্ত চলতি মূলধন"},"body":{"en":"Chamak’s application flow starts with a business profile and an invoice or purchase order. It describes digital transaction verification before funding approval, with inventory funding, receivables-to-cash and import-LC financing among its offerings. Chamak identifies itself as a financial technology company, not a bank; an application is not an approval or a quoted financing contract.","bn":"Chamak-এ ব্যবসার প্রোফাইল তৈরি করে ইনভয়েস বা পারচেজ অর্ডার জমা দিয়ে অর্থায়নের আবেদন করা যায়। লেনদেন যাচাইয়ের পর অনুমোদনের কথা বলা হয়েছে। স্টক কেনা, পাওনা বিলের বিপরীতে টাকা পাওয়া ও আমদানির এলসি অর্থায়ন তাদের সেবার মধ্যে আছে। Chamak নিজেকে ব্যাংক নয়, আর্থিক প্রযুক্তি প্রতিষ্ঠান হিসেবে পরিচয় দেয়। আবেদন করলেই অর্থায়ন নিশ্চিত হয় না।"},"sources":[{"title":"Trade-linked working capital","url":"https://chamakinc.com/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":"info@chamakinc.com","phone":"+8801321126100","address":{"en":"House 1145, Road 10, Avenue 10, Mirpur DOHS, Dhaka 1216, Bangladesh.","bn":"বাড়ি ১১৪৫, রোড ১০, অ্যাভিনিউ ১০, মিরপুর ডিওএইচএস, ঢাকা ১২১৬, বাংলাদেশ।"},"sources":[{"title":"Official contact information","url":"https://chamakinc.com/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
