INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_digibox', '{"sections":[{"id":"services","title":{"en":"Locker delivery & business integration","bn":"লকারে ডেলিভারি ও ব্যবসায় সংযোগ"},"body":{"en":"DIGIBOX lets a courier or service provider leave an item in a locker and sends the recipient an OTP or QR code for collection. Its service lines cover ecommerce parcels, banking documents, food and laundry. Businesses can connect through API or no-API workflows, while property owners can discuss hosting an installation. Pickup access depends on the location.","bn":"কুরিয়ার বা সেবাদাতা DIGIBOX লকারে জিনিস রেখে দিলে প্রাপক সংগ্রহের জন্য OTP বা QR কোড পান। ই-কমার্সের পার্সেল, ব্যাংকের কাগজপত্র, খাবার ও লন্ড্রির জন্য আলাদা সেবার বর্ণনা আছে। ব্যবসার ডেলিভারি প্রক্রিয়া API দিয়ে বা API ছাড়াও যুক্ত করা যায়। ভবনের মালিকরা লকার বসানোর বিষয়ে আলোচনা করতে পারেন। কখন সংগ্রহ করা যাবে, তা জায়গাভেদে দেখে নিতে হবে।"},"sources":[{"title":"Locker delivery & business integration","url":"https://digibox.com.bd/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":null,"phone":"+8809638556677","address":null,"sources":[{"title":"Official contact information","url":"https://digibox.com.bd/founders/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
