INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_ecovia', '{"sections":[{"id":"services","title":{"en":"Packaging range & custom orders","bn":"প্যাকেজিংয়ের ধরন ও কাস্টম অর্ডার"},"body":{"en":"Ecovia lists mailer, shopping, grocery, apparel and ziplock bags, sheets and electronics packaging. Businesses can request a quote specifying product type, quantity, dimensions and thickness. The company describes its materials as compostable; a buyer should obtain the applicable product certification and disposal requirements rather than assume every use or disposal setting is covered.","bn":"পণ্য পাঠানো, কেনাকাটা, মুদি পণ্য, পোশাক ও ইলেকট্রনিকসের জন্য বিভিন্ন ব্যাগ এবং শিট Ecovia-এর তালিকায় আছে। কী ধরনের প্যাকেট, কতগুলো, মাপ ও পুরুত্ব জানিয়ে দাম চাওয়া যায়। কোম্পানি এগুলোকে কম্পোস্টযোগ্য বলে বর্ণনা করে। কেনার আগে নির্দিষ্ট পণ্যের সনদ ও কী পরিবেশে পচবে, সে শর্তগুলো মিলিয়ে নেওয়া দরকার।"},"sources":[{"title":"Packaging range & custom orders","url":"https://www.ecoviaglobal.com/products","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":"info@ecoviaglobal.com","phone":"+8801817299956","address":{"en":"The Forum, West Tower, Level 19, 187–188/B Tejgaon Gulshan Link Road, Dhaka 1208, Bangladesh.","bn":"দ্য ফোরাম, ওয়েস্ট টাওয়ার, লেভেল ১৯, ১৮৭–১৮৮/বি তেজগাঁও গুলশান লিংক রোড, ঢাকা ১২০৮, বাংলাদেশ।"},"sources":[{"title":"Official contact information","url":"https://www.ecoviaglobal.com/contact-us","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
