INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_ezycourse', '{"sections":[{"id":"services","title":{"en":"Tools for course creators","bn":"কোর্স নির্মাতাদের টুল"},"body":{"en":"EzyCourse combines course delivery with communities, coaching bookings and membership subscriptions. Creators can build a website, sell digital products, run assessments and email campaigns, and offer a branded mobile app. Its audience is educators and knowledge-business operators who need teaching, sales and member access in the same service.","bn":"কোর্স, কমিউনিটি, কোচিংয়ের বুকিং ও মেম্বারশিপ সাবস্ক্রিপশন একসঙ্গে চালানো যায় EzyCourse-এ। ওয়েবসাইট তৈরি, ডিজিটাল পণ্য বিক্রি, পরীক্ষা নেওয়া ও ইমেইল পাঠানোর সুবিধাও আছে। নিজের ব্র্যান্ডে মোবাইল অ্যাপ দেওয়ার ব্যবস্থাও তালিকাভুক্ত। শেখানো, বিক্রি ও সদস্যদের প্রবেশাধিকার একই সেবায় সামলাতে চান এমন শিক্ষক ও কোর্স নির্মাতাদের জন্য প্রোডাক্টগুলো তৈরি।"},"sources":[{"title":"Tools for course creators","url":"https://ezycourse.com/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":null,"phone":null,"address":null,"sources":[{"title":"Official contact information","url":"https://ezycourse.com/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
INSERT INTO identity_events (id, organization_id, action, actor, created_at, detail_json) VALUES ('catalogue-profile-ezycourse', 'org_ezycourse', 'review', 'editorial:company-profile-catalogue', '2026-09-21', '{"scope":"Bilingual products, services and evidenced contact details. Existing editorial research dates preserved."}');
INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_fashol', '{"sections":[{"id":"services","title":{"en":"Farm sourcing & buyer platforms","bn":"খামার থেকে সংগ্রহ ও ক্রেতার প্ল্যাটফর্ম"},"body":{"en":"Fashol describes a supply chain that connects farmer procurement, hub grading, order matching and delivery. Jogaan handles farmer and input-side activity; Hyperfarm serves buyers such as restaurants and quick-commerce operators. Its site also describes wholesale and export services. Working-capital finance is presented as a planned 2026 offering, so it is not listed here as an established service.","bn":"কৃষকের কাছ থেকে পণ্য কেনা, হাবে মান বাছাই, অর্ডারের সঙ্গে মেলানো ও ক্রেতার কাছে পৌঁছানোর কাজ করে Fashol। কৃষক ও কৃষি উপকরণের দিকটি Jogaan-এ, আর রেস্তোরাঁসহ ব্যবসায়িক ক্রেতাদের অর্ডার Hyperfarm-এ সামলানোর কথা বলা হয়েছে। পাইকারি ও রপ্তানির সেবাও আছে। চলতি মূলধনের অর্থায়নকে সাইটে ২০২৬ সালের পরিকল্পনা বলা হয়েছে, তাই এখানে চালু সেবা হিসেবে ধরা হয়নি।"},"sources":[{"title":"Farm sourcing & buyer platforms","url":"https://fashol.com/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":null,"phone":"+8809613105505","address":null,"sources":[{"title":"Official contact information","url":"https://fashol.com/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
INSERT INTO identity_events (id, organization_id, action, actor, created_at, detail_json) VALUES ('catalogue-profile-fashol', 'org_fashol', 'review', 'editorial:company-profile-catalogue', '2026-09-21', '{"scope":"Bilingual products, services and evidenced contact details. Existing editorial research dates preserved."}');
INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_hishabee', '{"sections":[{"id":"services","title":{"en":"Shop management & stock finance","bn":"দোকানের হিসাব ও স্টকের অর্থায়ন"},"body":{"en":"Hishabee combines sales, purchase, expense, stock and due-collection records in a Bangla/English business app. Its inventory-finance flow lets a merchant choose stock and apply within the app; the site identifies Prime Bank as the lender paying the supplier directly. Eligibility, repayment and pricing remain subject to the actual financing offer.","bn":"Hishabee-তে বিক্রি, কেনাকাটা, খরচ, স্টক ও বাকি আদায়ের হিসাব রাখা যায়। অ্যাপটি বাংলা ও ইংরেজিতে ব্যবহার করা যায়। স্টক বেছে নেওয়ার সময় অর্থায়নের আবেদন করার ব্যবস্থাও আছে। সাইটের বর্ণনা অনুযায়ী ঋণদাতা Prime Bank সরাসরি সরবরাহকারীকে টাকা দেয়। কারা অর্থায়ন পাবেন, ফেরত দেওয়ার নিয়ম ও খরচ কত হবে, তা প্রকৃত প্রস্তাবের শর্ত দেখে বুঝে নিতে হয়।"},"sources":[{"title":"Shop management & stock finance","url":"https://www.hishabee.io/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":"support@hishabee.io","phone":"+8809638011199","address":{"en":"Level 2, 69/C Panthapath, Dhaka 1205.","bn":"লেভেল ২, ৬৯/সি পান্থপথ, ঢাকা ১২০৫।"},"sources":[{"title":"Official contact information","url":"https://www.hishabee.io/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
INSERT INTO identity_events (id, organization_id, action, actor, created_at, detail_json) VALUES ('catalogue-profile-hishabee', 'org_hishabee', 'review', 'editorial:company-profile-catalogue', '2026-09-21', '{"scope":"Bilingual products, services and evidenced contact details. Existing editorial research dates preserved."}');
INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_jatri', '{"sections":[{"id":"services","title":{"en":"Passenger booking & transport services","bn":"যাত্রীদের বুকিং ও পরিবহন সেবা"},"body":{"en":"Jatri’s passenger site offers bus tickets, launch tickets and car rental, with a multimode search option. It also provides separate routes for corporate customers and its transport platform. Passengers can search by origin, destination and travel date; availability and cancellation conditions depend on the selected service.","bn":"Jatri-তে বাস ও লঞ্চের টিকিট কাটা, গাড়ি ভাড়া নেওয়া এবং একাধিক ধরনের যাত্রা খোঁজার সুযোগ আছে। করপোরেট গ্রাহক ও পরিবহন প্ল্যাটফর্মের জন্য আলাদা লিংকও দেওয়া আছে। কোথা থেকে কোথায়, কোন দিনে যাবেন তা দিয়ে খোঁজা যায়। আসন পাওয়া ও বাতিলের শর্ত নির্ভর করে বেছে নেওয়া সেবার ওপর।"},"sources":[{"title":"Passenger booking & transport services","url":"https://jatri.co/bus","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":"info@jatri.co","phone":"09643404040","address":{"en":"House 15, Road 24, Gulshan 2, Dhaka 1212.","bn":"বাড়ি ১৫, রোড ২৪, গুলশান ২, ঢাকা ১২১২।"},"sources":[{"title":"Official contact information","url":"https://jatri.co/bus","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
