INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_dubotech', '{"sections":[{"id":"services","title":{"en":"Autonomous systems & integration","bn":"স্বয়ংক্রিয় যান ও প্রযুক্তি সংযুক্তি"},"body":{"en":"Dubotech develops autonomous vehicles and the FORTIS software layer that connects vehicles and sensors across sea, land and air. Its published applications include inspection, logistics and security. Alongside its own platforms, the company describes integrating autonomy into existing equipment, with monitoring and operator training.","bn":"জল, স্থল ও আকাশে চলা যান আর সেন্সর একসঙ্গে চালানোর সফটওয়্যার FORTIS বানায় Dubotech। নিজস্ব স্বয়ংক্রিয় যানের পাশাপাশি আগে থেকে থাকা যন্ত্রপাতিতেও এই প্রযুক্তি বসানোর কাজ করে। পরিদর্শন, পণ্য পরিবহন ও নিরাপত্তার কাজে ব্যবহারের কথা তাদের ওয়েবসাইটে আছে। যন্ত্রের কাজ পর্যবেক্ষণ ও অপারেটরদের প্রশিক্ষণও সেবার অংশ।"},"sources":[{"title":"Autonomous systems & integration","url":"https://dubotech.com/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":null,"phone":"+8801871729639","address":{"en":"Headquarters: House 13, Road 07, Block F, Banani, Dhaka, Bangladesh.","bn":"প্রধান কার্যালয়: বাড়ি ১৩, রোড ০৭, ব্লক এফ, বনানী, ঢাকা, বাংলাদেশ।"},"sources":[{"title":"Official contact information","url":"https://dubotech.com/contact","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
