INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_gozayaan', '{"sections":[{"id":"services","title":{"en":"Travel booking & assistance","bn":"ভ্রমণ বুকিং ও সহায়তা"},"body":{"en":"GoZayaan offers flight and hotel bookings, customised tours and visa assistance. Its published travel service describes both online booking and experience centres where travellers can discuss plans with a representative. Visa assistance is a booking-support service, not a promise of visa approval.","bn":"ফ্লাইট ও হোটেল বুক করা, নিজের প্রয়োজনমতো ট্যুর ঠিক করা এবং ভিসার আবেদনে সহায়তা নেওয়া যায় GoZayaan-এ। অনলাইনে বুকিংয়ের পাশাপাশি এক্সপেরিয়েন্স সেন্টারে প্রতিনিধির সঙ্গে ভ্রমণের পরিকল্পনা নিয়েও কথা বলা যায় বলে তাদের সাইটে উল্লেখ আছে। ভিসার কাজে সহায়তা পাওয়া মানে ভিসা পাওয়ার নিশ্চয়তা নয়।"},"sources":[{"title":"Travel booking & assistance","url":"https://bkash.gozayaan.com/about-us","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":"info@gozayaan.com","phone":"+8809678332211","address":null,"sources":[{"title":"Official contact information","url":"https://upay.gozayaan.com/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
