INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_loop-freight', '{"sections":[{"id":"services","title":{"en":"Freight coordination tools","bn":"মালামাল পরিবহনের কাজ গুছিয়ে নেওয়া"},"body":{"en":"Loop Freight’s published platform description gives shippers tools to schedule and track truck movements and manage transport records. Truck vendors can find loads and organise vehicles and drivers. The service also covers dispatch documents, communication and transport accounting.","bn":"কোন ট্রাকে কখন মাল যাবে, ট্রাক কোথায় আছে আর পরিবহনের হিসাব কী দাঁড়াল, এসব এক জায়গায় রাখার ব্যবস্থা আছে Loop Freight-এর প্রকাশিত সেবার বর্ণনায়। ট্রাকের মালিকেরাও কাজ খোঁজা এবং গাড়ি ও চালকের কাজ ভাগ করে দেওয়ার টুল পান। মাল পাঠানোর কাগজপত্র ও যোগাযোগের তথ্যও গুছিয়ে রাখা যায়।"},"sources":[{"title":"Freight coordination tools","url":"https://loopfreight.io/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":null,"phone":null,"address":null,"sources":[{"title":"Official contact information","url":"https://loopfreight.io/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
