INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_markopolo-ai', '{"sections":[{"id":"services","title":{"en":"Customer engagement for online stores","bn":"অনলাইন দোকানের গ্রাহকের সঙ্গে যোগাযোগ"},"body":{"en":"Markopolo.ai offers customer-engagement software for ecommerce businesses across email, SMS, WhatsApp, push notifications and AI voice. Its tools identify visitors, group audiences and automate follow-up after browsing, an abandoned cart or an unfinished checkout. These are product capabilities described by the company; sales-lift figures are not treated as established outcomes.","bn":"অনলাইন দোকানে কেউ পণ্য দেখে চলে গেলে বা কার্টে রেখেও অর্ডার শেষ না করলে, তাঁর সঙ্গে আবার যোগাযোগের কাজ সাজিয়ে নেওয়া যায় Markopolo.ai-তে। গ্রাহকদের আলাদা দলে ভাগ করে ইমেইল, SMS, WhatsApp, নোটিফিকেশন ও AI ভয়েসের মাধ্যমে বার্তা পাঠানোর টুল আছে। এখানে কোম্পানির বর্ণনা অনুযায়ী সুবিধাগুলো দেওয়া হলো, বিক্রি বাড়ার প্রচারমূলক হারকে নিশ্চিত ফল হিসেবে ধরা হয়নি।"},"sources":[{"title":"Customer engagement for online stores","url":"https://markopolo.ai/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":null,"phone":null,"address":null,"sources":[{"title":"Official contact information","url":"https://markopolo.ai/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
