INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_medeasy', '{"sections":[{"id":"services","title":{"en":"Prescription ordering & consultations","bn":"প্রেসক্রিপশন দিয়ে অর্ডার ও ডাক্তারের পরামর্শ"},"body":{"en":"MedEasy sells medicines and healthcare products online and offers video consultations with doctors. Its prescription-order flow asks customers to photograph a prescription, sign in and upload it; a pharmacist reviews it before an agent calls to confirm the order. This is distinct from selecting products directly from the catalogue.","bn":"ওষুধের নাম ধরে খুঁজে অর্ডার করা ছাড়াও MedEasy-তে প্রেসক্রিপশনের ছবি পাঠানো যায়। সে ক্ষেত্রে পরিষ্কার ছবি তুলে অ্যাকাউন্টে ঢুকে আপলোড করতে হয়। ফার্মাসিস্ট দেখে নেওয়ার পর একজন প্রতিনিধি ফোন করে অর্ডার কনফার্ম করেন। ওষুধ ও স্বাস্থ্যপণ্যের পাশাপাশি ভিডিও কলে ডাক্তারের পরামর্শ নেওয়ার সেবাও আছে।"},"sources":[{"title":"Prescription ordering & consultations","url":"https://medeasy.health/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":null,"phone":"+8809642661112","address":null,"sources":[{"title":"Official contact information","url":"https://medeasy.health/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
