INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_monsha', '{"sections":[{"id":"services","title":{"en":"Teaching materials & lesson planning","bn":"পাঠের পরিকল্পনা ও ক্লাসের উপকরণ"},"body":{"en":"Monsha helps teachers turn a topic, document, URL or learning goal into course outlines, units, lesson plans and classroom materials. Outputs include worksheets, quizzes and slides, with options to adjust grade level, reading difficulty and language. Teachers can export work into common document and presentation formats or learning-management systems.","bn":"ক্লাসে কী পড়াবেন, সেই বিষয় বা শেখার লক্ষ্য দিয়ে Monsha-তে পাঠের পরিকল্পনা শুরু করা যায়। নিজের ফাইল বা ওয়েব লিংকও দেওয়া যায়। সেখান থেকে কোর্সের রূপরেখা, লেসন প্ল্যান, ওয়ার্কশিট, কুইজ ও স্লাইড বানিয়ে শ্রেণি, ভাষা বা পড়ার কঠিনতা অনুযায়ী বদলে নেওয়ার টুল আছে। তৈরি উপকরণ ডকুমেন্ট, প্রেজেন্টেশন বা লার্নিং ম্যানেজমেন্ট সিস্টেমেও নেওয়া যায়।"},"sources":[{"title":"Teaching materials & lesson planning","url":"https://monsha.ai/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":null,"phone":null,"address":null,"sources":[{"title":"Official contact information","url":"https://monsha.ai/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
INSERT INTO identity_events (id, organization_id, action, actor, created_at, detail_json) VALUES ('catalogue-profile-monsha', 'org_monsha', 'review', 'editorial:company-profile-catalogue', '2026-09-21', '{"scope":"Bilingual products, services and evidenced contact details. Existing editorial research dates preserved."}');
