INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_nuport', '{"sections":[{"id":"services","title":{"en":"Orders, inventory & fulfilment","bn":"অর্ডার, মজুত ও পণ্য পাঠানোর কাজ"},"body":{"en":"Nuport connects Shopify and WooCommerce orders with inventory, warehouse fulfilment and courier workflows. Its published service covers storage, picking, packing, shipping labels and tracking, including integrations with Pathao, REDX, Carrybee and Steadfast. Merchants can also reconcile cash-on-delivery collections, record expenses and review profit by sales channel.","bn":"Shopify বা WooCommerce-এর অর্ডার থেকে গুদামের মজুত, প্যাকিং ও কুরিয়ারে পাঠানো পর্যন্ত কাজ গুছিয়ে নেওয়া যায় Nuport-এ। পণ্য রাখা, অর্ডারমতো পণ্য তুলে প্যাক করা, শিপিং লেবেল বানানো ও ডেলিভারি ট্র্যাক করার সেবা আছে। Pathao, REDX, Carrybee ও Steadfast-এর সঙ্গে সংযোগের কথাও দেওয়া আছে। বিক্রেতারা COD-এর টাকা মিলিয়ে নেওয়া, খরচ লেখা ও কোন মাধ্যমে কত লাভ হচ্ছে দেখার টুল পান।"},"sources":[{"title":"Orders, inventory & fulfilment","url":"https://www.nuport.io/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":"hello@nuport.io","phone":"01325072924","address":{"en":"Published Bangladesh locations: House 11, Road 17, Banani C/A, Dhaka 1212; and 8th Floor, 580 East Kazipara, MAS Square, Mirpur 10, Dhaka 1216.","bn":"বাংলাদেশে প্রকাশিত ঠিকানা: বাড়ি ১১, রোড ১৭, বনানী সি/এ, ঢাকা ১২১২। আরেকটি ঠিকানা: অষ্টম তলা, ৫৮০ পূর্ব কাজীপাড়া, MAS Square, মিরপুর ১০, ঢাকা ১২১৬।"},"sources":[{"title":"Official contact information","url":"https://www.nuport.io/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
