INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_ostad', '{"sections":[{"id":"services","title":{"en":"Courses & career-support tools","bn":"কোর্স ও ক্যারিয়ারের প্রস্তুতি"},"body":{"en":"Ostad offers live cohort-based and recorded courses in areas including software development, design, business, marketing, data and cybersecurity. It also lists corporate training, a CV builder, coding practice through Codemama and free preview classes. Career and placement support are services offered alongside learning.","bn":"সফটওয়্যার ডেভেলপমেন্ট, ডিজাইন, বিজনেস, মার্কেটিং, ডেটা ও সাইবার সিকিউরিটিসহ নানা বিষয়ে Ostad-এ লাইভ ব্যাচ ও রেকর্ড করা কোর্স আছে। আগে দেখে নেওয়ার জন্য ফ্রি ক্লাসও পাওয়া যায়। কোম্পানির কর্মীদের প্রশিক্ষণ, সিভি বানানোর টুল আর Codemama-তে কোডিং অনুশীলনের সুযোগ আলাদা করে দেওয়া আছে। ক্যারিয়ার গড়া ও চাকরি খোঁজার সহায়তাও দেয় Ostad।"},"sources":[{"title":"Courses & career-support tools","url":"https://ostad.app/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":null,"phone":null,"address":null,"sources":[{"title":"Official contact information","url":"https://ostad.app/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
