INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_pulsetech', '{"sections":[{"id":"services","title":{"en":"Pharmacy supply, software & retail","bn":"ফার্মেসির সরবরাহ, সফটওয়্যার ও দোকান"},"body":{"en":"PulseTech combines several parts of the pharmacy business: MedBox for medicine distribution and warehousing, MediPOS for pharmacy inventory and sales workflows, and ONE Pharmacy for a retail franchise network. It also describes embedded finance for the supply chain. These are separate services; access to finance depends on the relevant provider and terms.","bn":"ফার্মেসির জন্য ওষুধ সংগ্রহ থেকে দোকানের হিসাব পর্যন্ত কয়েকটি আলাদা সেবা চালায় PulseTech। MedBox-এ ওষুধ সরবরাহ ও গুদামের কাজ হয়। MediPOS দিয়ে মজুত, কেনাবেচা ও দোকানের দৈনন্দিন কাজের হিসাব রাখা যায়। ONE Pharmacy তাদের ফ্র্যাঞ্চাইজি দোকানের নেটওয়ার্ক। সরবরাহের সঙ্গে অর্থায়নের ব্যবস্থাও বর্ণনা করা আছে, তবে অর্থ পেতে সংশ্লিষ্ট সেবার শর্ত মিলতে হবে।"},"sources":[{"title":"Pharmacy supply, software & retail","url":"https://pulsetechltd.com/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":"info@pulsetechltd.com","phone":"+8809609080706","address":{"en":"115–116 BSTI Road, Dhaka 1208, Bangladesh. Singapore: 33A Pagoda Street, Singapore 059192.","bn":"১১৫–১১৬ বিএসটিআই রোড, ঢাকা ১২০৮, বাংলাদেশ। সিঙ্গাপুর: ৩৩এ প্যাগোডা স্ট্রিট, সিঙ্গাপুর ০৫৯১৯২।"},"sources":[{"title":"Official contact information","url":"https://pulsetechltd.com/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
