INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_relaxy', '{"sections":[{"id":"services","title":{"en":"Counselling & workplace programmes","bn":"কাউন্সেলিং ও কর্মীদের সহায়তা"},"body":{"en":"Relaxy lists individual, couples, family and teenage counselling, available online or through its clinic. It also offers mental-health programmes for businesses. Its Riri AI companion is a separate digital product from booked sessions with a human professional.","bn":"ব্যক্তিগত, দম্পতি, পরিবার ও কিশোরদের কাউন্সেলিংয়ের জন্য Relaxy-তে অনলাইন বা ক্লিনিকে সেশন নেওয়ার সুযোগ আছে। প্রতিষ্ঠানের কর্মীদের মানসিক স্বাস্থ্য নিয়ে কাজ করার প্রোগ্রামও দেয়। Riri নামের AI সহচরটি আলাদা ডিজিটাল প্রোডাক্ট, মানুষের সঙ্গে বুক করা কাউন্সেলিং সেশন নয়।"},"sources":[{"title":"Counselling & workplace programmes","url":"https://relaxy.com.bd/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":"info@relaxy.com.bd","phone":"01316055638","address":{"en":"House 22, Block H, Section 2, Avenue 3, Road 1, Mirpur 2, Milk Vita Road, Dhaka.","bn":"বাড়ি ২২, ব্লক এইচ, সেকশন ২, অ্যাভিনিউ ৩, রোড ১, মিরপুর ২, মিল্ক ভিটা রোড, ঢাকা।"},"sources":[{"title":"Official contact information","url":"https://relaxy.com.bd/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
INSERT INTO identity_events (id, organization_id, action, actor, created_at, detail_json) VALUES ('catalogue-profile-relaxy', 'org_relaxy', 'review', 'editorial:company-profile-catalogue', '2026-09-21', '{"scope":"Bilingual products, services and evidenced contact details. Existing editorial research dates preserved."}');
INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_revora', '{"sections":[{"id":"services","title":{"en":"Messaging, sales & support","bn":"মেসেজে বিক্রি ও গ্রাহকসেবা"},"body":{"en":"Revora, formerly MyAlice, offers a shared customer-message inbox with automation for sales, support and community interactions. Its product includes AI agents, WhatsApp campaigns and reporting, with ecommerce integrations including Shopify, WooCommerce, Salla and Zid. Teams can bring conversations from different channels into one workflow.","bn":"আগের MyAlice এখন Revora নামে গ্রাহকের মেসেজ, বিক্রি ও সাপোর্টের কাজ এক জায়গায় আনার সফটওয়্যার দেয়। আলাদা চ্যানেলের কথোপকথন একই ইনবক্সে এনে টিমের মধ্যে ভাগ করে নেওয়া যায়। AI এজেন্ট, WhatsApp ক্যাম্পেইন ও রিপোর্ট দেখার টুলও আছে। অনলাইন দোকানের সঙ্গে কাজ করার জন্য Shopify, WooCommerce, Salla ও Zid-এর সংযোগ দেওয়া আছে।"},"sources":[{"title":"Messaging, sales & support","url":"https://userevora.com/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":null,"phone":null,"address":null,"sources":[{"title":"Official contact information","url":"https://userevora.com/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
