INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_sharetrip', '{"sections":[{"id":"services","title":{"en":"Booking & travel support","bn":"বুকিং ও ভ্রমণের সহায়তা"},"body":{"en":"ShareTrip provides flight, hotel and holiday booking, visa assistance and car-booking support. Travellers can contact its support team with booking details by email or hotline. Its official news site also lists a Dhaka lounge and a Chattogram office for in-person contact.","bn":"ফ্লাইট, হোটেল ও ছুটির প্যাকেজ বুক করার পাশাপাশি ShareTrip-এ ভিসার কাজে সহায়তা এবং গাড়ি বুকিংয়ের সেবা আছে। কোনো বুকিংয়ে সমস্যা হলে বুকিংয়ের তথ্য নিয়ে ইমেইল বা হটলাইনে যোগাযোগ করা যায়। সরাসরি যোগাযোগের জন্য তাদের নিজস্ব নিউজ সাইটে ঢাকার লাউঞ্জ ও চট্টগ্রামের অফিসের ঠিকানাও দেওয়া আছে।"},"sources":[{"title":"Booking & travel support","url":"https://news.sharetrip.net/","publishedOn":null,"checkedAt":"2026-09-21"},{"title":"Car-booking support","url":"https://support.sharetrip.net/en/article/how-can-i-contact-customer-support-if-i-have-an-issue-1gh7p52/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":"ask@sharetrip.net","phone":"13701","address":{"en":"Dhaka lounge: 3rd Floor, House 1, Road 17, Block C, Banani, Dhaka 1213. Chattogram: BM Heights, 5th Floor, 318 Sheikh Mujib Road, Badamtoli, Agrabad.","bn":"ঢাকার লাউঞ্জ: তৃতীয় তলা, বাড়ি ১, রোড ১৭, ব্লক সি, বনানী, ঢাকা ১২১৩। চট্টগ্রাম: বিএম হাইটস, পঞ্চম তলা, ৩১৮ শেখ মুজিব রোড, বাদামতলী, আগ্রাবাদ।"},"sources":[{"title":"Official contact information","url":"https://news.sharetrip.net/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
