INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_shomvob', '{"sections":[{"id":"services","title":{"en":"Job search, recruitment & HR","bn":"চাকরি খোঁজা, নিয়োগ ও কর্মীদের কাজ"},"body":{"en":"Shomvob serves job seekers through vacancies and training, and employers through recruitment, outsourced staffing and payroll services. Its employer tools are distinct from the job-seeker application. The company also links to Shomvob HRM for workplace administration and an academy for training.","bn":"চাকরিপ্রার্থীরা Shomvob-এ বিজ্ঞপ্তি দেখে আবেদন ও প্রশিক্ষণের খোঁজ নিতে পারেন। আর কর্মী দরকার এমন প্রতিষ্ঠানের জন্য নিয়োগ, আউটসোর্সিংয়ের মাধ্যমে কর্মী দেওয়া ও বেতনের হিসাব সামলানোর সেবা আছে। চাকরিপ্রার্থী ও নিয়োগদাতার প্রবেশের জায়গা আলাদা। কর্মীদের দৈনন্দিন কাজ সামলানোর Shomvob HRM এবং প্রশিক্ষণের একাডেমিও তাদের সাইট থেকে পাওয়া যায়।"},"sources":[{"title":"Job search, recruitment & HR","url":"https://shomvob.com/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":null,"phone":"+8809638885588","address":{"en":"Published location: Baridhara DOHS, Dhaka, Bangladesh.","bn":"প্রকাশিত অবস্থান: বারিধারা ডিওএইচএস, ঢাকা, বাংলাদেশ।"},"sources":[{"title":"Official contact information","url":"https://shomvob.com/contact","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
