INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_shuttle', '{"sections":[{"id":"services","title":{"en":"Shared commuting & business transport","bn":"একসঙ্গে যাতায়াত ও প্রতিষ্ঠানের পরিবহন"},"body":{"en":"Shuttle’s published services cover scheduled shared commuting, women’s rides, employee transport for businesses and car rental. Shared rides follow service routes and schedules, while a business transport arrangement or rental is a separate booking. Confirm current routes and availability directly before planning a commute.","bn":"প্রকাশিত সেবার বর্ণনা অনুযায়ী Shuttle-এ নির্ধারিত রুটে একসঙ্গে যাতায়াত, নারীদের রাইড, প্রতিষ্ঠানের কর্মীদের পরিবহন ও গাড়ি ভাড়ার ব্যবস্থা আছে। শেয়ারড রাইডে রুট ও সময় মিলিয়ে নিতে হয়। আর প্রতিষ্ঠানের পরিবহন বা গাড়ি ভাড়ার বুকিং আলাদা। নিয়মিত যাতায়াতের পরিকল্পনা করার আগে বর্তমানে কোন রুটে সেবা চলছে, সরাসরি জেনে নিন।"},"sources":[{"title":"Shared commuting & business transport","url":"https://www.shuttlebd.com/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":null,"phone":null,"address":null,"sources":[{"title":"Official contact information","url":"https://www.shuttlebd.com/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
