INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_sokrio', '{"sections":[{"id":"services","title":{"en":"Field sales & distribution","bn":"মাঠপর্যায়ের বিক্রি ও ডিস্ট্রিবিউশন"},"body":{"en":"Sokrio provides distribution-management software for field sales teams. Published functions include mapping retail outlets, planning and validating routes, recording visits and attendance, taking orders, tracking stock and returns, and monitoring collections. Managers can review the field team’s activity and sales data through dashboards.","bn":"মাঠে কাজ করা সেলস টিমের জন্য দোকানের অবস্থান, যাওয়ার রুট, ভিজিট ও উপস্থিতির তথ্য এক জায়গায় রাখার সফটওয়্যার দেয় Sokrio। সেখান থেকেই অর্ডার নেওয়া, মজুত ও ফেরত পণ্যের হিসাব রাখা এবং টাকা আদায়ের অগ্রগতি দেখা যায়। ম্যানেজাররা ড্যাশবোর্ডে টিমের কাজ ও বিক্রির তথ্য মিলিয়ে নিতে পারেন।"},"sources":[{"title":"Field sales & distribution","url":"https://sokrio.com/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":null,"phone":"01920239873","address":{"en":"House 11, Road 21, Sector 4, Uttara, Dhaka 1230.","bn":"বাড়ি ১১, রোড ২১, সেক্টর ৪, উত্তরা, ঢাকা ১২৩০।"},"sources":[{"title":"Official contact information","url":"https://sokrio.com/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
