INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_solshare', '{"sections":[{"id":"services","title":{"en":"Energy trading, charging & rooftop solar","bn":"বিদ্যুৎ কেনাবেচা, চার্জিং ও ছাদে সৌরবিদ্যুৎ"},"body":{"en":"SOLshare works across distributed solar energy and electric mobility. SOLbazaar supports local energy exchange, while its mobility work covers smart batteries and charging. SOLroof offers commercial and industrial rooftop-solar installation and advice, with operating-expense and capital-expense models described separately on its product page.","bn":"সৌরবিদ্যুৎ উৎপাদন, স্থানীয়ভাবে বিদ্যুৎ কেনাবেচা ও বৈদ্যুতিক যানের চার্জিং নিয়ে SOLshare-এর আলাদা কাজ আছে। SOLbazaar-এ স্থানীয় বিদ্যুৎ বিনিময়ের ব্যবস্থা, আর যানবাহনের জন্য স্মার্ট ব্যাটারি ও চার্জিং নিয়ে কাজ করে। SOLroof-এর মাধ্যমে ব্যবসা ও কারখানার ছাদে সৌরবিদ্যুৎ বসানো এবং পরামর্শ নেওয়া যায়। এর খরচ চালানোর ও স্থাপনায় বিনিয়োগের মডেলগুলো প্রোডাক্টের পাতায় আলাদা করে দেওয়া আছে।"},"sources":[{"title":"Energy trading, charging & rooftop solar","url":"https://solshare.com/","publishedOn":null,"checkedAt":"2026-09-21"},{"title":"SOLroof - commercial and industrial rooftop services","url":"https://solshare.com/solar-rooftop/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":null,"phone":"+8801708458769","address":{"en":"LM Tower, 2nd Floor, Ka/87, Joar Shahara Bazar Road, Vatara, Dhaka 1229, Bangladesh.","bn":"এলএম টাওয়ার, দ্বিতীয় তলা, ক/৮৭, জোয়ার সাহারা বাজার রোড, ভাটারা, ঢাকা ১২২৯, বাংলাদেশ।"},"sources":[{"title":"Official contact information","url":"https://solshare.com/contact-us/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
