INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_tallykhata', '{"sections":[{"id":"services","title":{"en":"Bookkeeping & payments","bn":"দোকানের হিসাব ও পেমেন্ট"},"body":{"en":"TallyKhata provides digital records for small merchants, including sales, purchases, expenses, stock and customer or supplier dues. Its Bangla interface supports keeping everyday business records with backup. TallyPay is presented separately as a wallet and payment service, with QR payments, adding or withdrawing money and mobile recharge.","bn":"দোকানে কত বিক্রি হলো, কী কেনা হলো, খরচ কত আর কার কাছে বাকি আছে, এসব লিখে রাখা যায় TallyKhata-তে। বাংলায় হিসাব রাখার সঙ্গে মজুত দেখা ও তথ্যের ব্যাকআপের সুবিধাও আছে। TallyPay আলাদা ওয়ালেট ও পেমেন্ট সেবা হিসেবে দেখানো হয়েছে। সেখানে QR পেমেন্ট, টাকা যোগ করা বা তোলা এবং মোবাইল রিচার্জের সুবিধার কথা আছে।"},"sources":[{"title":"Bookkeeping & payments","url":"https://www.tallykhata.com/en/home-eng/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":null,"phone":null,"address":null,"sources":[{"title":"Official contact information","url":"https://www.tallykhata.com/en/home-eng/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
