INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_tiger-new-energy', '{"sections":[{"id":"services","title":{"en":"Battery service & swapping","bn":"ব্যাটারি ব্যবহার ও বদলে নেওয়া"},"body":{"en":"Tiger New Energy offers lithium-battery service and swapping infrastructure for electric vehicles. Its published model includes daily subscriptions and swap stations, alongside motorcycle batteries. An app provides battery and station information, connecting the physical battery service with a digital account.","bn":"বৈদ্যুতিক যানে ব্যবহার করার লিথিয়াম ব্যাটারি ও চার্জ শেষ হলে বদলে নেওয়ার স্টেশন নিয়ে কাজ করে Tiger New Energy। তাদের সেবার বর্ণনায় দৈনিক সাবস্ক্রিপশন ও মোটরসাইকেলের ব্যাটারিও আছে। অ্যাপে ব্যাটারি ও স্টেশনের তথ্য দেখে নেওয়া যায়, ফলে ব্যাটারি ব্যবহারের কাজের সঙ্গে ডিজিটাল অ্যাকাউন্টও যুক্ত থাকে।"},"sources":[{"title":"Battery service & swapping","url":"https://www.tigernewenergy.com/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":"contact@tigernewenergy.com","phone":"09606990120","address":{"en":"Bangladesh: 46 Gulshan Avenue, Dhaka 1212. Singapore: 20A Tanjong Pagar Road, Singapore 088443.","bn":"বাংলাদেশ: ৪৬ গুলশান অ্যাভিনিউ, ঢাকা ১২১২। সিঙ্গাপুর: ২০এ তানজং পাগার রোড, সিঙ্গাপুর ০৮৮৪৪৩।"},"sources":[{"title":"Official contact information","url":"https://www.tigernewenergy.com/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
