INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_tipsoi', '{"sections":[{"id":"services","title":{"en":"Devices & workplace software","bn":"যন্ত্র ও কর্মীদের কাজের সফটওয়্যার"},"body":{"en":"Tipsoi combines biometric devices with cloud software for attendance, shifts, leave and payroll. Its workplace products also cover visitor management, parking and access control. Device records feed workplace reporting and administrative workflows; security or compliance claims need their own verification.","bn":"আঙুলের ছাপ বা অন্য বায়োমেট্রিক যন্ত্রের তথ্য নিয়ে কর্মীদের উপস্থিতি, শিফট, ছুটি ও বেতনের হিসাব রাখার ক্লাউড সফটওয়্যার দেয় Tipsoi। অফিসে অতিথি আসা, পার্কিং ও প্রবেশের অনুমতি সামলানোর প্রোডাক্টও আছে। যন্ত্রে জমা হওয়া তথ্য থেকে রিপোর্ট ও প্রশাসনিক কাজ করা যায়।"},"sources":[{"title":"Devices & workplace software","url":"https://tipsoi.ai/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":null,"phone":null,"address":null,"sources":[{"title":"Official contact information","url":"https://tipsoi.ai/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
