INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_truck-lagbe', '{"sections":[{"id":"services","title":{"en":"Truck booking & business logistics","bn":"ট্রাক বুকিং ও ব্যবসার পণ্য পরিবহন"},"body":{"en":"Truck Lagbe lets customers specify pickup, destination, truck type, timing and goods, then select a vendor through its booking marketplace. It lists day hire, round trips, multiple stops, shifting and corporate logistics. Its transport-management system is a separate business tool from an individual truck booking.","bn":"কোথা থেকে কোথায় মাল যাবে, কী ধরনের ট্রাক লাগবে, সময় ও মালামালের তথ্য দিয়ে Truck Lagbe-তে বুকিং শুরু করা যায়। এরপর মার্কেটপ্লেসে ভাড়া ও সেবাদাতা মিলিয়ে বেছে নেওয়া হয়। দিনের জন্য ভাড়া, যাওয়া-আসা, একাধিক জায়গায় থামা, বাসা বদল ও প্রতিষ্ঠানের পণ্য পরিবহনের সেবা আছে। একটি ট্রাক বুক করার বাইরে ব্যবসার পরিবহন সামলানোর আলাদা সফটওয়্যারও দেয়।"},"sources":[{"title":"Truck booking & business logistics","url":"https://trucklagbe.com/en/home/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":"customercare@trucklagbe.com","phone":"+8809638000245","address":null,"sources":[{"title":"Official contact information","url":"https://trucklagbe.com/en/home/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
