INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_wedevs', '{"sections":[{"id":"services","title":{"en":"Software for marketplaces & business operations","bn":"মার্কেটপ্লেস ও ব্যবসার সফটওয়্যার"},"body":{"en":"weDevs develops software products for online businesses and website operators. Its portfolio includes Dokan for marketplaces, WP User Frontend for frontend publishing, WP Project Manager for projects and WP ERP for business administration. It also lists Appsero for software-product management, FlyWP for hosting operations and InboxWP for email delivery.","bn":"অনলাইন ব্যবসা ও ওয়েবসাইট চালানোর কয়েকটি আলাদা সফটওয়্যার বানায় weDevs। মার্কেটপ্লেসের জন্য Dokan, ওয়েবসাইটের সামনের দিক থেকে লেখা জমা দেওয়ার জন্য WP User Frontend, কাজের অগ্রগতি রাখার জন্য WP Project Manager এবং ব্যবসার প্রশাসনিক কাজের জন্য WP ERP আছে। সফটওয়্যার প্রোডাক্ট সামলাতে Appsero, হোস্টিংয়ের কাজে FlyWP ও ইমেইল পাঠাতে InboxWP-ও পাওয়া যায়।"},"sources":[{"title":"Software for marketplaces & business operations","url":"https://wedevs.com/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":null,"phone":null,"address":null,"sources":[{"title":"Official contact information","url":"https://wedevs.com/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
