INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_wegro', '{"sections":[{"id":"services","title":{"en":"Farmer services & market access","bn":"কৃষকের সেবা ও বাজারে বিক্রি"},"body":{"en":"WeGro combines farmer finance through banks and crowdfunding channels with agricultural inputs, market access and farming technology. It lists seeds, biofertilisers and crop-care products alongside climate-smart practices. Its market service connects production with buyers; participation should not be read as a guaranteed return or guaranteed sale.","bn":"কৃষকের অর্থায়ন, বীজ ও অন্যান্য উপকরণ পাওয়া এবং উৎপাদিত পণ্য বিক্রির বাজার নিয়ে একসঙ্গে কাজ করে WeGro। ব্যাংক ও ক্রাউডফান্ডিংয়ের মাধ্যমে অর্থায়নের কথা তাদের সাইটে আছে। বীজ, জৈবসার ও ফসলের যত্নের পণ্যের পাশাপাশি জলবায়ুর ঝুঁকি মাথায় রেখে চাষের প্রযুক্তিও দেয়। ক্রেতার সঙ্গে যোগাযোগের সুযোগকে নিশ্চিত বিক্রি বা নিশ্চিত লাভ ধরে নেওয়া যাবে না।"},"sources":[{"title":"Farmer services & market access","url":"https://www.wegro.global/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":"info@wegro.global","phone":"+8801322891563","address":{"en":"Bangladesh: House 42, Road 1, Block A, Niketon, Gulshan, Dhaka. Singapore: 160 Robinson Road, #14-04, Singapore 068914.","bn":"বাংলাদেশ: বাড়ি ৪২, রোড ১, ব্লক এ, নিকেতন, গুলশান, ঢাকা। সিঙ্গাপুর: ১৬০ রবিনসন রোড, #১৪-০৪, সিঙ্গাপুর ০৬৮৯১৪।"},"sources":[{"title":"Official contact information","url":"https://www.wegro.global/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
