INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_wpdeveloper', '{"sections":[{"id":"services","title":{"en":"WordPress products & group context","bn":"ওয়ার্ডপ্রেস প্রোডাক্ট ও মূল প্রতিষ্ঠান"},"body":{"en":"WPDeveloper is part of Startise, which identifies it as a WordPress product company. Its product range includes Essential Addons for Elementor, Essential Blocks for the WordPress editor, BetterDocs for knowledge bases and FAQs, EmbedPress for embedded media, BetterLinks for link management and SchedulePress for editorial scheduling.","bn":"Startise-এর অধীনে WPDeveloper ওয়ার্ডপ্রেসের প্রোডাক্ট বানায়। Elementor-এ ওয়েবসাইট সাজাতে Essential Addons, ওয়ার্ডপ্রেস এডিটরের জন্য Essential Blocks, সাহায্যের লেখা ও সাধারণ প্রশ্নের উত্তর রাখতে BetterDocs পাওয়া যায়। মিডিয়া বসাতে EmbedPress, লিংক সামলাতে BetterLinks আর লেখা প্রকাশের সময় ঠিক করতে SchedulePress-ও আছে।"},"sources":[{"title":"WordPress products & group context","url":"https://startise.com/","publishedOn":null,"checkedAt":"2026-09-21"},{"title":"Startise group and brands","url":"https://startise.com/about/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":null,"phone":null,"address":null,"sources":[{"title":"Official contact information","url":"https://startise.com/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
