INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_zatiq', '{"sections":[{"id":"services","title":{"en":"Online-store operations","bn":"অনলাইন দোকানের কাজ"},"body":{"en":"ZatiqEasy lets merchants create an online storefront and manage products, orders, inventory, payments and delivery workflows. Merchants can use a hosted store address or a custom domain and work through its merchant app. Zatiq also links to learning resources through Zatiq Academy.","bn":"ZatiqEasy-তে পণ্যের তথ্য দিয়ে অনলাইন দোকান খুলে অর্ডার, মজুত, পেমেন্ট ও ডেলিভারির কাজ সামলানো যায়। দোকানের জন্য তাদের দেওয়া ঠিকানা ব্যবহার করা বা নিজের ডোমেইন যুক্ত করার সুযোগ আছে। মার্চেন্ট অ্যাপ থেকেও কাজ করা যায়, আর শেখার উপকরণের জন্য Zatiq Academy-এর লিংক দেওয়া আছে।"},"sources":[{"title":"Online-store operations","url":"https://zatiqeasy.com/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":"info@zatiq.com","phone":"+8801969909069","address":{"en":"111 Somerset Road, #08-10A, 111 Somerset, Singapore 238164.","bn":"১১১ সমারসেট রোড, #০৮-১০এ, ১১১ সমারসেট, সিঙ্গাপুর ২৩৮১৬৪।"},"sources":[{"title":"Official contact information","url":"https://zatiqeasy.com/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
INSERT INTO identity_events (id, organization_id, action, actor, created_at, detail_json) VALUES ('catalogue-profile-zatiq', 'org_zatiq', 'review', 'editorial:company-profile-catalogue', '2026-09-21', '{"scope":"Bilingual products, services and evidenced contact details. Existing editorial research dates preserved."}');
INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_bangladesh-women-investors-network', '{"sections":[{"id":"services","title":{"en":"Women angel investors & founder support","bn":"নারী অ্যাঞ্জেল ইনভেস্টর ও ফাউন্ডারদের সহায়তা"},"body":{"en":"BWIN is Bangladesh Angels Network’s women-led sister chapter. It offers investor learning on diligence, valuation and risk, peer learning and access to selected opportunities. Members make their own investment decisions rather than contributing to a pooled BWIN fund. Mentoring founders is another way members can participate.","bn":"Bangladesh Angels Network-এর নারী নেতৃত্বাধীন শাখা BWIN-এ বিনিয়োগ যাচাই, ভ্যালুয়েশন ও ঝুঁকি নিয়ে শেখা এবং অন্য বিনিয়োগকারীদের সঙ্গে অভিজ্ঞতা মেলানোর সুযোগ আছে। বাছাই করা উদ্যোগের সঙ্গে যোগাযোগও হয়। সদস্যরা নিজেরাই বিনিয়োগের সিদ্ধান্ত নেন, BWIN-এর এক তহবিলে সবাই টাকা জমা দেন না। ফাউন্ডারদের মেন্টর হিসেবেও সদস্যরা যুক্ত হতে পারেন।"},"sources":[{"title":"Women angel investors & founder support","url":"https://bdangels.co/bwin","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":"hello@bdangels.co","phone":"+8801724937741","address":{"en":"Contact through Bangladesh Angels Network: Level 3, House 27, Road 12, Niketon, Gulshan 1, Dhaka 1212.","bn":"Bangladesh Angels Network-এর মাধ্যমে যোগাযোগ: লেভেল ৩, বাড়ি ২৭, রোড ১২, নিকেতন, গুলশান ১, ঢাকা ১২১২।"},"sources":[{"title":"Official contact information","url":"https://bdangels.co/bwin","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
