INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_anchorless-bangladesh', '{"sections":[{"id":"services","title":{"en":"Founder access & fund team","bn":"ফাউন্ডারদের যোগাযোগ ও ফান্ডের টিম"},"body":{"en":"Anchorless Bangladesh focuses on businesses using technology or data to scale, with potential to expand internationally. Its published investment approach is primarily seed, with selective pre-seed and post-seed participation. Founders can access an investment-application route through its website.","bn":"প্রযুক্তি বা ডেটা কাজে লাগিয়ে বড় হতে এবং দেশের বাইরের বাজারে যেতে পারে, এমন ব্যবসায় আগ্রহী Anchorless Bangladesh। মূলত সিড পর্যায়ে বিনিয়োগ করে, বাছাই করা প্রি-সিড ও পরবর্তী পর্যায়ের উদ্যোগেও অংশ নেয়। বিনিয়োগের আবেদন করার লিংক তাদের ওয়েবসাইটে পাওয়া যায়।"},"sources":[{"title":"Founder access & fund team","url":"https://www.anchorless.vc/","publishedOn":null,"checkedAt":"2026-09-21"},{"title":"Fund team and portfolio founders","url":"https://www.anchorless.vc/people","publishedOn":null,"checkedAt":"2026-09-21"},{"title":"Anchorless investment approach and portfolio","url":"https://www.anchorless.vc/portfolio","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":null,"phone":null,"address":null,"sources":[{"title":"Official contact information","url":"https://www.anchorless.vc/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
