INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_bangladesh-startup-investment-company-plc-bsic', '{"sections":[{"id":"services","title":{"en":"Governance & co-investment process","bn":"বিনিয়োগের সিদ্ধান্ত ও যৌথ বিনিয়োগ"},"body":{"en":"BSIC describes an independent investment committee and a process covering sourcing, diligence, approval and portfolio monitoring. Its published co-investment route begins with a founder securing an institutional lead investor, followed by BSIC assessment and joint diligence. The process describes a route to consideration, not automatic matching capital or a funding commitment to every applicant.","bn":"বিনিয়োগের প্রস্তাব খোঁজা, যাচাই, অনুমোদন ও পরে পোর্টফোলিওর খোঁজ রাখার ধাপগুলো BSIC-এর সাইটে দেওয়া আছে। সিদ্ধান্তের জন্য স্বাধীন ইনভেস্টমেন্ট কমিটির কথাও বলা হয়েছে। প্রকাশিত যৌথ বিনিয়োগের পদ্ধতিতে আগে ফাউন্ডারকে একটি প্রাতিষ্ঠানিক লিড ইনভেস্টর পেতে হয়। এরপর BSIC-এর মূল্যায়ন ও যৌথ যাচাইয়ের ধাপ আসে। আবেদন করলেই সমপরিমাণ অর্থ মিলবে, এমন নিশ্চয়তা এই প্রক্রিয়া থেকে ধরে নেওয়া যায় না।"},"sources":[{"title":"Governance & co-investment process","url":"https://www.bsic.vc/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":null,"phone":null,"address":null,"sources":[{"title":"Official contact information","url":"https://www.bsic.vc/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
