INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_dekko-isho-venture-capital-divc', '{"sections":[{"id":"services","title":{"en":"Support beyond capital","bn":"বিনিয়োগের বাইরেও সহায়তা"},"body":{"en":"DIVC describes operational support alongside early-stage capital: legal matters, hiring, technology, branding, marketing and growth. Founders can submit a pitch through its website. Support is described across idea validation, initial products and expansion; the published offer does not mean every service is included in every investment.","bn":"আইডিয়া যাচাই, প্রথম প্রোডাক্ট বানানো বা নতুন বাজারে যাওয়ার সময় বিনিয়োগের পাশাপাশি কাজের সহায়তাও দেয় বলে DIVC জানিয়েছে। এর মধ্যে আইনগত কাজ, নিয়োগ, প্রযুক্তি, ব্র্যান্ডিং, মার্কেটিং ও ব্যবসা বাড়ানোর সহায়তা আছে। ওয়েবসাইটে পিচ জমা দেওয়া যায়। তবে কোন উদ্যোগ কোন সহায়তা পাবে, সেটা আলাদা করে মিলিয়ে নিতে হবে।"},"sources":[{"title":"Support beyond capital","url":"https://www.di.vc/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":null,"phone":null,"address":{"en":"Forum West Tower, Level 19, 187–188/B Bir Uttam Shawkat Sarak, Tejgaon, Dhaka 1208, Bangladesh.","bn":"ফোরাম ওয়েস্ট টাওয়ার, লেভেল ১৯, ১৮৭–১৮৮/বি বীর উত্তম শওকত সড়ক, তেজগাঁও, ঢাকা ১২০৮, বাংলাদেশ।"},"sources":[{"title":"Official contact information","url":"https://www.di.vc/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
