INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_bangladesh-venture-capital-limited-bvcl', '{"sections":[{"id":"services","title":{"en":"Published support & contact location","bn":"প্রকাশিত সহায়তা ও যোগাযোগের ঠিকানা"},"body":{"en":"BVCL’s current website describes capital, mentoring, industry introductions and strategic guidance for startups and growth-stage businesses. It publishes a Dhaka contact address, but the reviewed page does not identify a current investment team, a named portfolio or a detailed application process.","bn":"স্টার্টআপ ও বড় হতে থাকা ব্যবসার জন্য মূলধন, মেন্টরিং, খাতের মানুষের সঙ্গে পরিচয় এবং কৌশলগত পরামর্শের কথা BVCL-এর বর্তমান সাইটে আছে। যোগাযোগের জন্য ঢাকার ঠিকানাও দেওয়া হয়েছে। তবে দেখা পাতায় বর্তমান ইনভেস্টমেন্ট টিম, নামসহ পোর্টফোলিও বা আবেদনের বিস্তারিত পদ্ধতি পাওয়া যায়নি।"},"sources":[{"title":"Published support & contact location","url":"https://venture.com.bd/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":null,"phone":null,"address":{"en":"101 Sukrabad, Mirpur Road, Dhanmondi, Dhaka 1207, Bangladesh.","bn":"১০১ শুক্রাবাদ, মিরপুর রোড, ধানমন্ডি, ঢাকা ১২০৭, বাংলাদেশ।"},"sources":[{"title":"Official contact information","url":"https://venture.com.bd/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
