INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_yy-ventures', '{"sections":[{"id":"services","title":{"en":"Incubation & advisory services","bn":"ইনকিউবেশন ও পরামর্শসেবা"},"body":{"en":"YY Ventures supports early-stage social businesses with training, tailored consultation, coworking, business services and access to investors. It also advises foundations, impact funds, companies and development or government agencies on social-business programmes, including accelerator design, innovation challenges and venture building.","bn":"শুরুর পর্যায়ের সামাজিক ব্যবসাকে প্রশিক্ষণ, প্রয়োজনমতো পরামর্শ, একসঙ্গে কাজের জায়গা ও বিনিয়োগকারীদের সঙ্গে যোগাযোগের সহায়তা দেয় YY Ventures। ফাউন্ডেশন, ইমপ্যাক্ট ফান্ড, কোম্পানি, উন্নয়ন সংস্থা ও সরকারি সংস্থাও সামাজিক ব্যবসার প্রোগ্রাম তৈরিতে তাদের পরামর্শ নিতে পারে। অ্যাক্সেলারেটর সাজানো, নতুন সমাধানের প্রতিযোগিতা চালানো ও উদ্যোগ গড়ে তোলার কাজও এর মধ্যে আছে।"},"sources":[{"title":"Incubation & advisory services","url":"https://yy.ventures/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":null,"phone":"+8801329744860","address":{"en":"9th Floor, Grameen Telecom Bhaban, Mirpur 1, Dhaka 1216, Bangladesh.","bn":"নবম তলা, গ্রামীণ টেলিকম ভবন, মিরপুর ১, ঢাকা ১২১৬, বাংলাদেশ।"},"sources":[{"title":"Official contact information","url":"https://yy.ventures/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
INSERT INTO identity_events (id, organization_id, action, actor, created_at, detail_json) VALUES ('catalogue-profile-yy-ventures', 'org_yy-ventures', 'review', 'editorial:company-profile-catalogue', '2026-09-21', '{"scope":"Bilingual products, services and evidenced contact details. Existing editorial research dates preserved."}');
INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_accelerating-asia-ventures', '{"sections":[{"id":"services","title":{"en":"Accelerator & founder support","bn":"অ্যাক্সেলারেটর ও ফাউন্ডারদের সহায়তা"},"body":{"en":"Accelerating Asia combines early-stage investment with an accelerator for startups in South and Southeast Asia. Its published offer emphasises hands-on work with founders alongside capital and access to its network. The official portfolio highlights include Aunkur (iPAGE) and Inovace Technologies, the company behind Tipsoi.","bn":"দক্ষিণ ও দক্ষিণ-পূর্ব এশিয়ার শুরুর পর্যায়ের স্টার্টআপে বিনিয়োগের সঙ্গে অ্যাক্সেলারেটর চালায় Accelerating Asia। মূলধনের পাশাপাশি ফাউন্ডারদের সঙ্গে সরাসরি কাজ ও নিজেদের নেটওয়ার্কে যোগাযোগের সহায়তার কথা জানিয়েছে। তাদের প্রকাশিত পোর্টফোলিওতে Aunkur বা iPAGE এবং Tipsoi-এর প্রতিষ্ঠান Inovace Technologies-ও দেখা যায়।"},"sources":[{"title":"Accelerator & founder support","url":"https://www.acceleratingasia.com/","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":"team@acceleratingasia.com","phone":null,"address":null,"sources":[{"title":"Official contact information","url":"https://www.acceleratingasia.com/","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
