INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_idlc-venture-capital', '{"sections":[{"id":"services","title":{"en":"Application status","bn":"আবেদনের বর্তমান অবস্থা"},"body":{"en":"On 21 September 2026, IDLC Venture Capital’s application page said applications were closed and Fund I was exhausted, with no current investing. It described a plan for a second fund in 2027. That is a stated plan, not an open application window or a confirmed future launch.","bn":"২০২৬ সালের ২১ সেপ্টেম্বর দেখা আবেদন পাতায় IDLC Venture Capital জানিয়েছে, আবেদন বন্ধ এবং প্রথম ফান্ডের অর্থ বরাদ্দ শেষ হওয়ায় তারা এখন নতুন বিনিয়োগ করছে না। ২০২৭ সালে দ্বিতীয় ফান্ড চালুর পরিকল্পনার কথা আছে। এটাকে এখন আবেদন নেওয়া হচ্ছে বা ভবিষ্যতের ফান্ড চালু নিশ্চিত, এমন তথ্য হিসেবে ধরা যাবে না।"},"sources":[{"title":"Application status","url":"https://www.idlcvc.com/coming-soon-03","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":null,"phone":null,"address":{"en":"Symphony, 4th Floor, Road 142, Gulshan South Avenue, Bir Uttam Mir Shawkat Sarak, Dhaka 1212.","bn":"সিম্ফনি, চতুর্থ তলা, রোড ১৪২, গুলশান সাউথ অ্যাভিনিউ, বীর উত্তম মীর শওকত সড়ক, ঢাকা ১২১২।"},"sources":[{"title":"Official contact information","url":"https://www.idlcvc.com/coming-soon-03","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
