INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_silq', '{"sections":[{"id":"services","title":{"en":"Group structure & operations","bn":"গ্রুপ ও তার কার্যক্রম"},"body":{"en":"ShopUp’s official history says ShopUp and Gulf B2B marketplace Sary combined in April 2025 to form SILQ. Its group leadership is presented separately from ShopUp’s Bangladesh management. In Bangladesh, the listed products remain Mokam for commerce and REDX for logistics; a group role should not be confused with a country-company role.","bn":"ShopUp-এর প্রকাশিত ইতিহাস অনুযায়ী, ২০২৫ সালের এপ্রিলে ShopUp ও উপসাগরীয় অঞ্চলের বিটুবি মার্কেটপ্লেস Sary মিলে SILQ গঠন করে। গ্রুপের নেতৃত্ব ও বাংলাদেশের ShopUp পরিচালনার দায়িত্ব আলাদা করে দেখানো আছে। বাংলাদেশে পণ্য কেনাবেচার Mokam ও লজিস্টিকসের REDX-এর লিংকও দেওয়া আছে। তাই গ্রুপের পদকে বাংলাদেশের কোম্পানির পদ বলে ধরে নেওয়া ঠিক হবে না।"},"sources":[{"title":"Group structure & operations","url":"https://www.shopup.org/about","publishedOn":null,"checkedAt":"2026-09-21"}],"links":[]}],"contact":{"email":null,"phone":null,"address":null,"sources":[{"title":"Official contact information","url":"https://www.shopup.org/about","publishedOn":null,"checkedAt":"2026-09-21"}]}}', '2026-09-21');
